Plan: identify the seller columns as those before the “Min Price > 0” column, then for each answer row find the minimum positive value and collect all matching headers. Join tied headers with commas and write the resulting text values into P2:P7.

```python
import shutil
import openpyxl

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

ws = wb.active
vws = vals[ws.title] if ws.title in vals else vals.active

def clean(v):
    if v is None:
        return ""
    return str(v).strip()

# Locate the Seller answer column and the Min Price > 0 column.
seller_col = None
min_col = None
for c in range(1, vws.max_column + 1):
    h = clean(vws.cell(row=1, column=c).value).lower()
    if h == "seller":
        seller_col = c
    if h == "min price > 0":
        min_col = c

if seller_col is None:
    seller_col = 16  # P

if min_col is None:
    end_col = seller_col - 2 if seller_col > 3 else max(2, vws.max_column - 2)
else:
    end_col = min_col - 1

start_col = 2
if end_col < start_col:
    end_col = max(start_col, vws.max_column - 2)

# Answer region is P2:P7.
for r in range(2, 8):
    candidates = []
    for c in range(start_col, end_col + 1):
        v = vws.cell(row=r, column=c).value
        if isinstance(v, bool):
            continue
        try:
            num = float(v)
        except (TypeError, ValueError):
            continue
        if num > 0:
            header = clean(vws.cell(row=1, column=c).value)
            if not header:
                header = openpyxl.utils.get_column_letter(c)
            candidates.append((num, header))

    if candidates:
        min_val = min(x[0] for x in candidates)
        names = []
        seen = set()
        for val, name in candidates:
            if abs(val - min_val) <= 1e-9 and name not in seen:
                seen.add(name)
                names.append(name)
        ws.cell(row=r, column=seller_col).value = ",".join(names)
    else:
        ws.cell(row=r, column=seller_col).value = None

print("Answer sheet:", ws.title)
print("Seller columns:", start_col, "to", end_col)
for r in range(2, 8):
    print(r, ws.cell(row=r, column=seller_col).value)

wb.save(OUT)
